<script lang="ts">import {labels,type Language} from '$lib/series/i18n';let {prompt,id='prompt',lang='ko'}:{prompt:string;id?:string;lang?:Language}=$props();let ui=$derived(labels[lang]);let copied=$state(false);let message=$state('');async function copy(){try{await navigator.clipboard.writeText(prompt);copied=true;message=ui.copySuccess;}catch{message=ui.copyFailure;}}</script><section class="prompt-panel" lang={lang} aria-labelledby={id+'-title'}><div class="prompt-toolbar"><h2 id={id+'-title'}>{ui.promptTitle}</h2><button onclick={copy}>{copied?ui.copied:ui.copy}</button></div><p role="status">{message||ui.promptHelp}</p><!-- svelte-ignore a11y_no_noninteractive_tabindex (Focusable scroll region for keyboard readers.) --><div class="code-region" tabindex="0" role="region" aria-label={ui.promptFull}><pre>{prompt}</pre></div></section>
